import sys
from collections import deque

def solve():
    input_data = sys.stdin.readline().strip()
    if not input_data:
        return
    t = int(input_data)

    for _ in range(t):
        n_line = sys.stdin.readline().strip()
        if not n_line:
            break
        n = int(n_line)

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, sys.stdin.readline().split())
            adj[u].append(v)
            adj[v].append(u)

        def query(nodes):
            print(f"? {len(nodes)}", end="")
            for node in nodes:
                print(f" {node}", end="")
            print()
            sys.stdout.flush()

            resp = sys.stdin.readline().split()
            if not resp:
                return None, None
            x, d = int(resp[0]), int(resp[1])
            if x == -1 and d == -1:
                sys.exit(0)
            return x, d

        def bfs(start_node):
            dist = [-1] * (n + 1)
            dist[start_node] = 0
            q = deque([start_node])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return dist

        root = 1
        best_node, best_dist = query([root])

        candidates = []
        for i in range(1, n + 1):
            if i != best_node:
                res_node, res_dist = query([i])
                if res_dist < best_dist:
                    best_dist = res_dist
                    best_node = res_node

        dist_from_best = bfs(best_node)

        neighbors = adj[best_node]
        if len(neighbors) == 0:
            pass
        else:
            cand_list = neighbors
            res_node, res_dist = query(cand_list)

            if res_dist < best_dist:
                best_node = res_node
                best_dist = res_dist
                dist_from_best = bfs(best_node)

        candidates = []
        for node in range(1, n + 1):
            if dist_from_best[node] == best_dist:
                candidates.append(node)

        if len(candidates) == 1:
            s = candidates[0]
            f = s
        else:
            s, f = candidates[0], candidates[1]

        print(f"! {s} {f}")
        sys.stdout.flush()
        status = sys.stdin.readline().strip()
        if status == "Incorrect":
            sys.exit(0)

if __name__ == "__main__":
    solve()
